/// The `locale` translation of an English source, if the catalog has one.
pub(super) fn lookup(locale: &str, source: &str) -> Option<&'static str> {
    let index = ENTRIES.binary_search_by(|(key, _)| (*key).cmp(source)).ok()?;
    ENTRIES[index]
        .1
        .iter()
        .find(|(candidate, _)| *candidate == locale)
        .map(|(_, translation)| *translation)
}

/// Every English source, for matching relayed text against templates.
pub(super) fn sources() -> impl Iterator<Item = &'static str> {
    ENTRIES.iter().map(|(source, _)| *source)
}
